import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type CongratulationsProps = Record<string, any>;

const Congratulations: React.FC<CongratulationsProps> = ({
  titleText = "CONGRATULATIONS",
  titleColor = "#FFD700", // Yellow gold
  backgroundColor = "#111111", // Dark background to make yellow pop
  transparentBackground = false,
  fontSize = 120,
  durationInSeconds = 5,
}) => {
  // Load heavy bold font
  useFontLoader(["Poppins"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors with background
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Split text for staggered animation
  const characters = titleText.split("");

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Poppins",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        overflow: "hidden",
      }}
    >
      <div
        style={{
          display: "flex",
          flexWrap: "wrap",
          justifyContent: "center",
          alignItems: "center",
          width: "90%",
          gap: fontSize * 0.05,
        }}
      >
        {characters.map((char, i) => {
          // Stagger delay per character
          const delay = i * 3;

          // Spring physics for entrance
          const spr = spring({
            frame: frame - delay,
            fps,
            config: {
              damping: 12,
              stiffness: 200,
              mass: 0.5,
            },
          });

          // Continuous floating wave after entrance
          const wave = Math.sin((frame - delay) * 0.1) * 10;
          // Only apply wave after initial entry stabilizes somewhat
          const waveOpacity = interpolate(frame - delay, [20, 40], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });
          const translateY = interpolate(spr, [0, 1], [100, 0]) + (wave * waveOpacity);
          
          const opacity = interpolate(frame - delay, [0, 5], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });

          const scale = interpolate(spr, [0, 1], [0, 1]);
          const rotate = interpolate(spr, [0, 1], [-45, 0]);

          return (
            <span
              key={i}
              style={{
                color: titleColor,
                fontSize: fontSize,
                fontWeight: 900,
                display: "inline-block",
                transform: `scale(${scale}) translateY(${translateY}px) rotate(${rotate}deg)`,
                opacity,
                textShadow: "0px 4px 20px rgba(255, 215, 0, 0.4)", // Glow effect matching yellow
                lineHeight: 1.1,
              }}
            >
              {char === " " ? "\u00A0" : char}
            </span>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default Congratulations;